//! Full worker/TUN/WireGuard transport benchmark against a controlled authenticated peer.
use crate::{config::WireguardConfig,connection::Connection,linux,packet::{Packet,PacketPool,PacketQueue},performance::{Options,UdpBackend},session::{Session,Output},stream::{FramedIo,Receive}};
use std::{fs::File,io::{Read,Write},net::{UdpSocket,TcpListener,TcpStream},os::fd::{AsFd,AsRawFd},sync::{Arc,atomic::{AtomicBool,Ordering}},time::{Duration,Instant,SystemTime,UNIX_EPOCH},thread,process::Command};
use base64::{Engine,engine::general_purpose::STANDARD};
#[path="../tests/common/mod.rs"] mod common;
fn emit(v:serde_json::Value){println!("HOUR_JSON {}",v);}
fn ip(a:&[&str]){assert!(Command::new("ip").args(a).status().unwrap().success());}
fn thread_cpu()->f64{let mut t:libc::timespec=unsafe{std::mem::zeroed()};assert_eq!(unsafe{libc::clock_gettime(libc::CLOCK_THREAD_CPUTIME_ID,&mut t)},0);t.tv_sec as f64+t.tv_nsec as f64/1e9}
fn process_cpu()->f64{let mut t:libc::timespec=unsafe{std::mem::zeroed()};assert_eq!(unsafe{libc::clock_gettime(libc::CLOCK_PROCESS_CPUTIME_ID,&mut t)},0);t.tv_sec as f64+t.tv_nsec as f64/1e9}
fn packet_thread()->i32{for e in std::fs::read_dir("/proc/self/task").unwrap(){let p=e.unwrap().path();if std::fs::read_to_string(p.join("comm")).unwrap_or_default().starts_with("protun-next"){return p.file_name().unwrap().to_str().unwrap().parse().unwrap();}}panic!("packet thread missing")}
fn ticks(tid:i32)->f64{let s=std::fs::read_to_string(format!("/proc/self/task/{tid}/stat")).unwrap();let f:Vec<_>=s.rsplit_once(')').unwrap().1.split_whitespace().collect();(f[11].parse::<u64>().unwrap()+f[12].parse::<u64>().unwrap())as f64/unsafe{libc::sysconf(libc::_SC_CLK_TCK)}as f64}
fn echo(p:&mut[u8]){assert_eq!(p[0]>>4,4);let h=(p[0]&15)as usize*4;assert_eq!(p[9],17);for i in 0..4{p.swap(12+i,16+i);}for i in 0..2{p.swap(h+i,h+2+i);}p[h+6..h+8].fill(0);p[10..12].fill(0);let mut sum:u32=p[..h].chunks_exact(2).map(|x|u16::from_be_bytes([x[0],x[1]])as u32).sum();while sum>65535{sum=(sum&65535)+(sum>>16);}p[10..12].copy_from_slice(&(!(sum as u16)).to_be_bytes());}
trait Duplex:Read+Write+Send{}impl Duplex for TcpStream{}impl Duplex for rustls::StreamOwned<rustls::ServerConnection,TcpStream>{}
enum Peer{Udp{socket:UdpSocket,tx:crate::linux_batch::Batch,rx:crate::linux_batch::Batch,first:Option<Vec<u8>>},Stream(FramedIo<Box<dyn Duplex>>)}
impl Peer{
 fn receive(&mut self,p:&mut Packet,pool:&mut PacketPool)->bool{match self{Self::Udp{socket,rx,first,..}=>{if let Some(v)=first.take(){p.writable()[..v.len()].copy_from_slice(&v);p.set_len(v.len()).unwrap();true}else{matches!(rx.receive(socket,p,pool).unwrap(),Receive::Packet)}},Self::Stream(s)=>match s.receive(p){Ok(Receive::Packet)=>true,Ok(_)=>false,Err(crate::Error::Io(e))if matches!(e.kind(),std::io::ErrorKind::WouldBlock|std::io::ErrorKind::TimedOut|std::io::ErrorKind::Interrupted|std::io::ErrorKind::UnexpectedEof)=>false,Err(e)=>panic!("peer receive {e}")}}}
 fn queue(&mut self,data:&[u8],q:&mut PacketQueue,pool:&mut PacketPool){let mut p=pool.take().unwrap();p.writable()[..data.len()].copy_from_slice(data);p.set_len(data.len()).unwrap();match self{Self::Udp{..}=>q.push(p).ok().unwrap(),Self::Stream(s)=>s.queue(p).ok().unwrap()}}
 fn flush(&mut self,q:&mut PacketQueue,pool:&mut PacketPool){match self{Self::Udp{socket,tx,..}=>{while tx.flush(socket,q,pool).unwrap(){thread::yield_now();}},Self::Stream(s)=>{while s.pending()>0{s.flush(pool).unwrap();}match s.io_mut().flush(){Ok(())=>{},Err(e)if matches!(e.kind(),std::io::ErrorKind::WouldBlock|std::io::ErrorKind::TimedOut)=>{},Err(e)=>panic!("peer flush {e}")}}}}
}
fn options(name:&str)->Options{let mut o=Options::default();o.compact_pool=!name.contains("full");o.in_place_crypto=!name.contains("copy");o.unbuffered_tls=name.contains("unbuffered");o.udp_backend=if name.starts_with("uring"){UdpBackend::IoUring}else if name.starts_with("portable"){UdpBackend::Portable}else{UdpBackend::Batch};o.udp_offload=name.contains("offload");o}
fn one(proto:&str,name:&str,size:usize,round:usize,seconds:f64,window:usize,latency:bool,vnet:bool){
 unsafe{std::env::set_var("BENCH_BUFFERS","128");std::env::remove_var("BENCH_SINGLE");std::env::remove_var("BENCH_GSO");std::env::remove_var("BENCH_GRO");}
 let tun=File::options().read(true).write(true).open("/dev/net/tun").unwrap();let mut req=[0u8;40];req[..4].copy_from_slice(b"pnh1");req[16..18].copy_from_slice(&((libc::IFF_TUN|libc::IFF_NO_PI|if vnet{libc::IFF_VNET_HDR}else{0})as i16).to_ne_bytes());assert_eq!(unsafe{libc::ioctl(tun.as_raw_fd(),libc::TUNSETIFF,req.as_mut_ptr())},0);
 if vnet{let h:libc::c_int=10;assert_eq!(unsafe{libc::ioctl(tun.as_raw_fd(),libc::TUNSETVNETHDRSZ,&h)},0);assert_eq!(unsafe{libc::ioctl(tun.as_raw_fd(),libc::TUNSETOFFLOAD,libc::TUN_F_CSUM|libc::TUN_F_TSO4|libc::TUN_F_TSO6|libc::TUN_F_USO4|libc::TUN_F_USO6)},0);}
 ip(&["link","set","lo","up"]);ip(&["addr","add","10.2.0.2/32","dev","pnh1"]);ip(&["link","set","pnh1","mtu","9000","up"]);ip(&["route","add","10.2.0.3/32","dev","pnh1"]);
 let udp=proto=="udp";let u=UdpSocket::bind("127.0.0.1:0").unwrap();u.set_read_timeout(Some(Duration::from_secs(5))).unwrap();let listener=TcpListener::bind("127.0.0.1:0").unwrap();let endpoint=if udp{u.local_addr().unwrap()}else{listener.local_addr().unwrap()};let tls_peer=proto=="stealth";let stop=Arc::new(AtomicBool::new(false));let done=stop.clone();
 let peer=thread::Builder::new().name("controlled-peer".into()).spawn(move||{let mut peer=if udp{let mut v=vec![0;65535];let(n,from)=u.recv_from(&mut v).unwrap();v.truncate(n);u.connect(from).unwrap();u.set_nonblocking(true).unwrap();let mut o=Options::default();o.udp_backend=UdpBackend::Batch;o.udp_offload=true;let tx=crate::linux_batch::Batch::new(&u,o);let rx=crate::linux_batch::Batch::new(&u,o);Peer::Udp{socket:u,tx,rx,first:Some(v)}}else{let(tcp,_)=listener.accept().unwrap();tcp.set_nodelay(true).unwrap();tcp.set_read_timeout(Some(Duration::from_millis(10))).unwrap();tcp.set_write_timeout(Some(Duration::from_secs(5))).unwrap();let io:Box<dyn Duplex>=if tls_peer{Box::new(rustls::StreamOwned::new(rustls::ServerConnection::new(common::server()).unwrap(),tcp))}else{Box::new(tcp)};Peer::Stream(FramedIo::new(io,64).unwrap())};
 let now=linux::boottime().unwrap();let wall=SystemTime::now().duration_since(UNIX_EPOCH).unwrap();let mut s=Session::new([9;32],Session::public_key([7;32]),None,now,wall).unwrap();let mut pool=PacketPool::new(132,65535).unwrap();let mut p=pool.take().unwrap();let mut out=vec![0;65535];let mut wire=vec![0;65535];let mut q=PacketQueue::new(64).unwrap();let c=thread_cpu();let mut count=0u64;let deadline=Instant::now()+Duration::from_secs(90);
 while !done.load(Ordering::Relaxed){assert!(Instant::now()<deadline);let mut got=false;for _ in 0..32{if !peer.receive(&mut p,&mut pool){break;}got=true;match s.decrypt(p.data(),&mut out).unwrap(){Output::Network(n)=>{peer.queue(&out[..n],&mut q,&mut pool);peer.flush(&mut q,&mut pool);},Output::Tunnel(n)=>{echo(&mut out[..n]);let Output::Network(n)=s.encrypt(&out[..n],&mut wire).unwrap()else{panic!()};peer.queue(&wire[..n],&mut q,&mut pool);count+=1;if count%16==0||window==1{peer.flush(&mut q,&mut pool);}},_=>{}}}peer.flush(&mut q,&mut pool);if !got{thread::yield_now();}}
 (thread_cpu()-c,count)}).unwrap();
 let text=format!("[Interface]\nPrivateKey={}\nAddress=10.2.0.2/32\nMTU=1280\n[Peer]\nPublicKey={}\nEndpoint={endpoint}\nAllowedIPs=10.2.0.3/32\n",STANDARD.encode([7;32]),STANDARD.encode(Session::public_key([9;32])));let conf=WireguardConfig::parse(&text).unwrap();let o=options(name);let tr=match proto{"udp"=>linux::Transport::Udp,"tcp"=>linux::Transport::Tcp,"stealth"=>linux::Transport::Stealth(crate::stealth::SniStrategy::Explicit("cover.test".into())),_=>panic!()}.with_performance(o);
 let begin=Instant::now();let mut con=Connection::start(tun.as_fd(),conf,"lo".into(),tr).unwrap();let app=UdpSocket::bind("10.2.0.2:0").unwrap();app.connect("10.2.0.3:9000").unwrap();app.set_read_timeout(Some(Duration::from_secs(5))).unwrap();let mut body=vec![0x5a;size];let mut recv=vec![0;65535];app.send(&body).unwrap();let n=app.recv(&mut recv).unwrap();assert_eq!(&recv[..n],body);let cold_ms=begin.elapsed().as_secs_f64()*1000.0;
 let tid=packet_thread();let wc=ticks(tid);let pc=process_cpu();let start=Instant::now();let mut packets=0usize;let mut samples=Vec::new();let mut aggregate=vec![0;size*window];if vnet{let seg=size as libc::c_int;assert_eq!(unsafe{libc::setsockopt(app.as_raw_fd(),libc::SOL_UDP,libc::UDP_SEGMENT,(&seg as *const libc::c_int).cast(),4)},0);}let deadline=start+Duration::from_secs_f64(seconds);
 while Instant::now()<deadline {let t=Instant::now();for j in 0..window{body[..8].copy_from_slice(&((packets+j)as u64).to_le_bytes());if vnet{aggregate[j*size..(j+1)*size].copy_from_slice(&body);}else{app.send(&body).unwrap();}}if vnet{app.send(&aggregate).unwrap();}let mut seen=0u64;for _ in 0..window{let n=app.recv(&mut recv).unwrap();assert_eq!(n,size);let seq=u64::from_le_bytes(recv[..8].try_into().unwrap())as usize;assert!(seq>=packets&&seq<packets+window);let bit=1u64<<(seq-packets);assert_eq!(seen&bit,0,"duplicate response");seen|=bit;assert!(recv[8..n].iter().all(|b|*b==0x5a));}packets+=window;if latency{samples.push(t.elapsed().as_secs_f64()*1e6);}}
 let elapsed=start.elapsed().as_secs_f64();let wcpu=ticks(tid)-wc;let procpu=process_cpu()-pc;let before=con.snapshot();stop.store(true,Ordering::Relaxed);let counters=con.disconnect_and_wait().unwrap();let(refcpu,refpackets)=peer.join().unwrap();let rss=std::fs::read_to_string("/proc/self/status").unwrap();let rsskb=rss.lines().find(|l|l.starts_with("VmHWM:")).and_then(|l|l.split_whitespace().nth(1)).and_then(|n|n.parse::<usize>().ok());samples.sort_by(f64::total_cmp);let pct=|p:f64|if samples.is_empty(){None}else{Some(samples[((samples.len()-1)as f64*p)as usize])};
 if proto=="udp" && name.starts_with("uring"){assert!(counters.io.io_uring_completions>0,"uring requested but not active");assert_eq!(counters.io.kernel_fallbacks,0);}if proto=="udp"&&o.udp_offload{assert!(counters.io.gso_datagrams>0||window==1,"GSO not exercised");}
 if vnet{assert!(counters.tun_reads<(packets as u64)/2,"TUN aggregation not exercised");}assert_eq!(counters.invalid_packets,0);emit(serde_json::json!({"test":"full-worker-controlled-peer","kernel":std::fs::read_to_string("/proc/sys/kernel/osrelease").unwrap().trim(),"arch":std::env::consts::ARCH,"transport":proto,"variant":name,"payload":size,"round":round,"window":window,"latency":latency,"vnet":vnet,"seconds":elapsed,"delivered_bytes":packets*size,"Mbps":packets as f64*size as f64*8.0/elapsed/1e6,"worker_cpu_ns_per_byte":wcpu*1e9/(packets*size)as f64,"worker_cpu_resolution_hz":unsafe{libc::sysconf(libc::_SC_CLK_TCK)},"whole_process_cpu_ns_per_byte":procpu*1e9/(packets*size)as f64,"reference_total_cpu_seconds":refcpu,"reference_packets":refpackets,"cold_echo_ms":cold_ms,"latency_p50_us":pct(0.5),"latency_p95_us":pct(0.95),"latency_p99_us":pct(0.99),"process_peak_rss_kib":rsskb,"counters":counters,"state":format!("{:?}",before.state),"scope":"real production packet worker and TUN, WireGuard over selected transport, authenticated controlled echo peer; UDP application workload, not Proton/HTTPS/forwarding acceptance"}));
}
pub fn run(){let a:Vec<_>=std::env::args().collect();one(&a[1],&a[2],a[3].parse().unwrap(),a[4].parse().unwrap(),a[5].parse().unwrap(),a[6].parse().unwrap(),a[7]=="1",a[8]=="1");}
